-- Hosbah (MH-576 D5): one row per "run this script on N servers" request. Exactly one of script_id
-- (a team script.sql row) or builtin_name (internal/scripts/builtin, e.g. "caddy", "php") is set —
-- never both, never neither. params is the JSON the run was started with: {"args": {...},
-- "env": {...}} — plaintext values that are not marked secret; secret values are sealed per target
-- server (script_run_servers do not hold plaintext either, only the operation they started, whose
-- own params are sealed the same way a deploy's env is). status rolls up the per-server rows:
-- running while any server row is pending/running, ok when every one finished ok, failed if any did.
ALTER TABLE script_runs ADD CONSTRAINT script_runs_status_check CHECK (status IN ('running', 'ok', 'failed'));
ALTER TABLE script_runs ADD CONSTRAINT script_runs_one_source_check CHECK ((script_id IS NOT NULL) <> (builtin_name IS NOT NULL));
CREATE INDEX script_runs_team_idx ON script_runs (team_id, created_at DESC);
CREATE INDEX script_runs_script_idx ON script_runs (team_id, script_id) WHERE script_id IS NOT NULL;
